#!/usr/bin/env Rscript
all<-commandArgs(trailingOnly=FALSE);self<-normalizePath(sub("^--file=","",grep("^--file=",all,value=TRUE)[[1]]),winslash="/");root<-normalizePath(file.path(dirname(self),"../.."),winslash="/");`%||%`<-function(x,y)if(is.null(x)||!length(x))y else x;source(file.path(root,"app/shiny/R/fitness_result_state.R"))
expected<-c(queued="Fitness analysis queued",running="Fitness analysis running",preview_success="Preview complete",cached_success="Cached result reused",success="Fitness analysis complete",failed="Fitness analysis failed",cancelled="Fitness analysis cancelled",stale="Fitness analysis process ended unexpectedly");stopifnot(all(vapply(names(expected),function(x)identical(fitness_job_status_message(x),unname(expected[[x]])),FALSE)),!grepl("complete",fitness_job_status_message("failed"),ignore.case=TRUE));tmp<-tempfile(fileext=".csv");write.csv(data.frame(feature_id="x",final_call="none"),tmp,row.names=FALSE);stopifnot(validate_fitness_success("success",tmp)$valid,!validate_fitness_success("failed",tmp)$valid,!validate_fitness_success("success",paste0(tmp,".missing"))$valid);cat("PASS\n")
